3	import androidx.annotation.NonNull;
4	import androidx.annotation.Nullable;
5	import androidx.collection.ArrayMap;
6	import androidx.collection.SimpleArrayMap;
7	import com.bumptech.glide.util.CachedHashCodeArrayMap;
8	import java.security.MessageDigest;
9	
10	/** A set of {@link Option Options} to apply to in memory and disk cache keys. */
11	public final class Options implements Key {
12	  private final ArrayMap<Option<?>, Object> values = new CachedHashCodeArrayMap<>();
13	
14	  public void putAll(@NonNull Options other) {
15	    values.putAll((SimpleArrayMap<Option<?>, Object>) other.values);
16	  }
17	
18	  @NonNull
19	  public <T> Options set(@NonNull Option<T> option, @NonNull T value) {
20	    values.put(option, value);
21	    return this;
22	  }
23	
24	  // TODO(b/234614365): Expand usage of this method in BaseRequestOptions so that it's usable for
25	  // other options.
26	  public Options remove(@NonNull Option<?> option) {
27	    values.remove(option);
28	    return this;
29	  }
30	
31	  @Nullable
32	  @SuppressWarnings("unchecked")
33	  public <T> T get(@NonNull Option<T> option) {
34	    return values.containsKey(option) ? (T) values.get(option) : option.getDefaultValue();
35	  }
36	
37	  @Override
38	  public boolean equals(Object o) {
39	    if (o instanceof Options) {
40	      Options other = (Options) o;
41	      return values.equals(other.values);
42	    }
43	    return false;
44	  }
45	
46	  @Override
47	  public int hashCode() {
48	    return values.hashCode();
49	  }
50	
51	  @Override
52	  public void updateDiskCacheKey(@NonNull MessageDigest messageDigest) {
53	    for (int i = 0; i < values.size(); i++) {
54	      Option<?> key = values.keyAt(i);
55	      Object value = values.valueAt(i);
56	      updateDiskCacheKey(key, value, messageDigest);
57	    }
58	  }
59	
60	  @Override
61	  public String toString() {
62	    return "Options{" + "values=" + values + '}';
63	  }
64	
65	  @SuppressWarnings("unchecked")
66	  private static <T> void updateDiskCacheKey(
67	      @NonNull Option<T> option, @NonNull Object value, @NonNull MessageDigest md) {
68	    option.update((T) value, md);
69	  }
70	}
