1	package com.bumptech.glide.load;
2	
3	import androidx.annotation.NonNull;
4	import androidx.annotation.Nullable;
5	import com.bumptech.glide.util.Preconditions;
6	import java.security.MessageDigest;
7	
8	/**
9	 * Defines available component (decoders, encoders, model loaders etc.) options with optional
10	 * default values and the ability to affect the resource disk cache key used by {@link
11	 * com.bumptech.glide.load.engine.DiskCacheStrategy#RESOURCE}.
12	 *
13	 * <p>Implementations must either be unique (usually declared as static final variables), or
14	 * implement {@link #equals(Object)} and {@link #hashCode()}.
15	 *
16	 * <p>Implementations can implement {@link #update(Object, MessageDigest)} to make sure that the
17	 * disk cache key includes the specific option set.
18	 *
19	 * @param <T> The type of the option ({@link Integer}, {@link
20	 *     android.graphics.Bitmap.CompressFormat} etc.), must implement {@link #equals(Object)} and
21	 *     {@link #hashCode()}.
22	 */
23	public final class Option<T> {
24	  private static final CacheKeyUpdater<Object> EMPTY_UPDATER =
25	      new CacheKeyUpdater<Object>() {
26	        @Override
27	        public void update(
28	            @NonNull byte[] keyBytes, @NonNull Object value, @NonNull MessageDigest messageDigest) {
29	          // Do nothing.
30	        }
31	      };
32	
33	  private final T defaultValue;
34	  private final CacheKeyUpdater<T> cacheKeyUpdater;
35	  private final String key;
36	  private volatile byte[] keyBytes;
37	
38	  /**
39	   * Returns a new {@link Option} that does not affect disk cache keys with a {@code null} default
40	   * value.
41	   *
42	   * @param key A unique package prefixed {@link String} that identifies this option (must be stable
43	   *     across builds, so {@link Class#getName()} should <em>not</em> be used).
44	   */
45	  @NonNull
46	  public static <T> Option<T> memory(@NonNull String key) {
47	    return new Option<>(key, null, Option.<T>emptyUpdater());
48	  }
49	
50	  /**
51	   * Returns a new {@link Option} that does not affect disk cache keys with the given value as the
52	   * default value.
53	   *
54	   * @param key A unique package prefixed {@link String} that identifies this option (must be stable
55	   *     across builds, so {@link Class#getName()} should <em>not</em> be used).
56	   */
57	  @NonNull
58	  public static <T> Option<T> memory(@NonNull String key, @NonNull T defaultValue) {
59	    return new Option<>(key, defaultValue, Option.<T>emptyUpdater());
60	  }
61	
62	  /**
63	   * Returns a new {@link Option} that uses the given {@link
64	   * com.bumptech.glide.load.Option.CacheKeyUpdater} to update disk cache keys.
65	   *
66	   * @param key A unique package prefixed {@link String} that identifies this option (must be stable
67	   *     across builds, so {@link Class#getName()} should <em>not</em> be used).
68	   */
69	  @NonNull
70	  public static <T> Option<T> disk(
71	      @NonNull String key, @NonNull CacheKeyUpdater<T> cacheKeyUpdater) {
72	    return new Option<>(key, null, cacheKeyUpdater);
73	  }
74	
75	  /**
76	   * Returns a new {@link Option} that uses the given {@link
77	   * com.bumptech.glide.load.Option.CacheKeyUpdater} to update disk cache keys and provides the
78	   * given value as the default value.
79	   *
80	   * @param key A unique package prefixed {@link String} that identifies this option (must be stable
81	   *     across builds, so {@link Class#getName()} should <em>not</em> be used).
82	   */
83	  @NonNull
84	  public static <T> Option<T> disk(
85	      @NonNull String key, @Nullable T defaultValue, @NonNull CacheKeyUpdater<T> cacheKeyUpdater) {
86	    return new Option<>(key, defaultValue, cacheKeyUpdater);
87	  }
88	
89	  private Option(
90	      @NonNull String key, @Nullable T defaultValue, @NonNull CacheKeyUpdater<T> cacheKeyUpdater) {
91	    this.key = Preconditions.checkNotEmpty(key);
92	    this.defaultValue = defaultValue;
93	    this.cacheKeyUpdater = Preconditions.checkNotNull(cacheKeyUpdater);
94	  }
95	
96	  /** Returns a reasonable default to use if no other value is set, or {@code null}. */
97	  // Public API.
98	  @SuppressWarnings("WeakerAccess")
99	  @Nullable
100	  public T getDefaultValue() {
101	    return defaultValue;
102	  }
103	
104	  /**
105	   * Updates the given {@link MessageDigest} used to construct a cache key with the given value
106	   * using the {@link com.bumptech.glide.load.Option.CacheKeyUpdater} optionally provided in the
107	   * constructor.
108	   */
109	  public void update(@NonNull T value, @NonNull MessageDigest messageDigest) {
110	    cacheKeyUpdater.update(getKeyBytes(), value, messageDigest);
111	  }
112	
113	  @NonNull
114	  private byte[] getKeyBytes() {
115	    if (keyBytes == null) {
116	      keyBytes = key.getBytes(Key.CHARSET);
117	    }
118	    return keyBytes;
119	  }
120	
121	  @Override
122	  public boolean equals(Object o) {
123	    if (o instanceof Option) {
124	      Option<?> other = (Option<?>) o;
125	      return key.equals(other.key);
126	    }
127	    return false;
128	  }
129	
130	  @Override
131	  public int hashCode() {
132	    return key.hashCode();
133	  }
134	
135	  @NonNull
136	  @SuppressWarnings("unchecked")
137	  private static <T> CacheKeyUpdater<T> emptyUpdater() {
138	    return (CacheKeyUpdater<T>) EMPTY_UPDATER;
139	  }
140	
141	  @Override
142	  public String toString() {
143	    return "Option{" + "key='" + key + '\'' + '}';
144	  }
145	
146	  /**
147	   * An interface that updates a {@link MessageDigest} with the given value as part of a process to
148	   * generate a disk cache key.
149	   *
150	   * @param <T> The type of the option.
151	   */
152	  public interface CacheKeyUpdater<T> {
153	    /**
154	     * Updates the given {@link MessageDigest} with the bytes of the given key (to avoid incidental
155	     * value collisions when values are not particularly unique) and value.
156	     *
157	     * <p>If your {@link Option} shouldn't affect the disk cache key, you should not implement this
158	     * class and use {@link Option#memory(String)} or {@link Option#memory(String, Object)} instead.
159	     *
160	     * @param keyBytes The bytes of the {@link String} used as the key for this particular {@link
161	     *     Option}. Should be added to the {@code messageDigest} using {@link
162	     *     MessageDigest#update(byte[])} by all implementations if the digest is updated with the
163	     *     given {@code value} parameter.
164	     * @param value The value of of this particular option. Typically you should convert the value
165	     *     to a byte array using some stable mechanism and then call {@link
166	     *     MessageDigest#update(byte[])} to update the given digest.
167	     */
168	    void update(@NonNull byte[] keyBytes, @NonNull T value, @NonNull MessageDigest messageDigest);
169	  }
170	}
