1	package com.bumptech.glide.load;
2	
3	import android.content.Context;
4	import androidx.annotation.NonNull;
5	import com.bumptech.glide.load.engine.Resource;
6	import java.security.MessageDigest;
7	import java.util.Arrays;
8	import java.util.Collection;
9	
10	/**
11	 * A transformation that applies one or more transformations in iteration order to a resource.
12	 *
13	 * @param <T> The type of {@link com.bumptech.glide.load.engine.Resource} that will be transformed.
14	 */
15	public class MultiTransformation<T> implements Transformation<T> {
16	  private final Collection<? extends Transformation<T>> transformations;
17	
18	  @SafeVarargs
19	  @SuppressWarnings("varargs")
20	  public MultiTransformation(@NonNull Transformation<T>... transformations) {
21	    if (transformations.length == 0) {
22	      throw new IllegalArgumentException(
23	          "MultiTransformation must contain at least one Transformation");
24	    }
25	    this.transformations = Arrays.asList(transformations);
26	  }
27	
28	  public MultiTransformation(@NonNull Collection<? extends Transformation<T>> transformationList) {
29	    if (transformationList.isEmpty()) {
30	      throw new IllegalArgumentException(
31	          "MultiTransformation must contain at least one Transformation");
32	    }
33	    this.transformations = transformationList;
34	  }
35	
36	  @NonNull
37	  @Override
38	  public Resource<T> transform(
39	      @NonNull Context context, @NonNull Resource<T> resource, int outWidth, int outHeight) {
40	    Resource<T> previous = resource;
41	
42	    for (Transformation<T> transformation : transformations) {
43	      Resource<T> transformed = transformation.transform(context, previous, outWidth, outHeight);
44	      if (previous != null && !previous.equals(resource) && !previous.equals(transformed)) {
45	        previous.recycle();
46	      }
47	      previous = transformed;
48	    }
49	    return previous;
50	  }
51	
52	  @Override
53	  public boolean equals(Object o) {
54	    if (o instanceof MultiTransformation) {
55	      MultiTransformation<?> other = (MultiTransformation<?>) o;
56	      return transformations.equals(other.transformations);
57	    }
58	    return false;
59	  }
60	
61	  @Override
62	  public int hashCode() {
63	    return transformations.hashCode();
64	  }
65	
66	  @Override
67	  public void updateDiskCacheKey(@NonNull MessageDigest messageDigest) {
68	    for (Transformation<T> transformation : transformations) {
69	      transformation.updateDiskCacheKey(messageDigest);
70	    }
71	  }
72	}
