1	package com.bumptech.glide.provider;
2	
3	import androidx.annotation.NonNull;
4	import com.bumptech.glide.load.ResourceDecoder;
5	import com.bumptech.glide.util.Synthetic;
6	import java.util.ArrayList;
7	import java.util.HashMap;
8	import java.util.List;
9	import java.util.Map;
10	
11	/**
12	 * Contains an ordered list of {@link ResourceDecoder}s capable of decoding arbitrary data types
13	 * into arbitrary resource types from highest priority decoders to lowest priority decoders.
14	 */
15	@SuppressWarnings("rawtypes")
16	public class ResourceDecoderRegistry {
17	  private final List<String> bucketPriorityList = new ArrayList<>();
18	  private final Map<String, List<Entry<?, ?>>> decoders = new HashMap<>();
19	
20	  public synchronized void setBucketPriorityList(@NonNull List<String> buckets) {
21	    List<String> previousBuckets = new ArrayList<>(bucketPriorityList);
22	    bucketPriorityList.clear();
23	    // new ArrayList(List) and ArrayList#addAll(List) are both broken on some verisons of Android,
24	    // see #3296
25	    for (String bucket : buckets) {
26	      bucketPriorityList.add(bucket);
27	    }
28	    for (String previousBucket : previousBuckets) {
29	      if (!buckets.contains(previousBucket)) {
30	        // Keep any buckets from the previous list that aren't included here, but but them at the
31	        // end.
32	        bucketPriorityList.add(previousBucket);
33	      }
34	    }
35	  }
36	
37	  @NonNull
38	  @SuppressWarnings("unchecked")
39	  public synchronized <T, R> List<ResourceDecoder<T, R>> getDecoders(
40	      @NonNull Class<T> dataClass, @NonNull Class<R> resourceClass) {
41	    List<ResourceDecoder<T, R>> result = new ArrayList<>();
42	    for (String bucket : bucketPriorityList) {
43	      List<Entry<?, ?>> entries = decoders.get(bucket);
44	      if (entries == null) {
45	        continue;
46	      }
47	      for (Entry<?, ?> entry : entries) {
48	        if (entry.handles(dataClass, resourceClass)) {
49	          result.add((ResourceDecoder<T, R>) entry.decoder);
50	        }
51	      }
52	    }
53	    // TODO: cache result list.
54	
55	    return result;
56	  }
57	
58	  @NonNull
59	  @SuppressWarnings("unchecked")
60	  public synchronized <T, R> List<Class<R>> getResourceClasses(
61	      @NonNull Class<T> dataClass, @NonNull Class<R> resourceClass) {
62	    List<Class<R>> result = new ArrayList<>();
63	    for (String bucket : bucketPriorityList) {
64	      List<Entry<?, ?>> entries = decoders.get(bucket);
65	      if (entries == null) {
66	        continue;
67	      }
68	      for (Entry<?, ?> entry : entries) {
69	        if (entry.handles(dataClass, resourceClass)
70	            && !result.contains((Class<R>) entry.resourceClass)) {
71	          result.add((Class<R>) entry.resourceClass);
72	        }
73	      }
74	    }
75	    return result;
76	  }
77	
78	  public synchronized <T, R> void append(
79	      @NonNull String bucket,
80	      @NonNull ResourceDecoder<T, R> decoder,
81	      @NonNull Class<T> dataClass,
82	      @NonNull Class<R> resourceClass) {
83	    getOrAddEntryList(bucket).add(new Entry<>(dataClass, resourceClass, decoder));
84	  }
85	
86	  public synchronized <T, R> void prepend(
87	      @NonNull String bucket,
88	      @NonNull ResourceDecoder<T, R> decoder,
89	      @NonNull Class<T> dataClass,
90	      @NonNull Class<R> resourceClass) {
91	    getOrAddEntryList(bucket).add(0, new Entry<>(dataClass, resourceClass, decoder));
92	  }
93	
94	  @NonNull
95	  private synchronized List<Entry<?, ?>> getOrAddEntryList(@NonNull String bucket) {
96	    if (!bucketPriorityList.contains(bucket)) {
97	      // Add this unspecified bucket as a low priority bucket.
98	      bucketPriorityList.add(bucket);
99	    }
100	    List<Entry<?, ?>> entries = decoders.get(bucket);
101	    if (entries == null) {
102	      entries = new ArrayList<>();
103	      decoders.put(bucket, entries);
104	    }
105	    return entries;
106	  }
107	
108	  private static class Entry<T, R> {
109	    private final Class<T> dataClass;
110	    @Synthetic final Class<R> resourceClass;
111	    @Synthetic final ResourceDecoder<T, R> decoder;
112	
113	    public Entry(
114	        @NonNull Class<T> dataClass,
115	        @NonNull Class<R> resourceClass,
116	        ResourceDecoder<T, R> decoder) {
117	      this.dataClass = dataClass;
118	      this.resourceClass = resourceClass;
119	      this.decoder = decoder;
120	    }
121	
122	    public boolean handles(@NonNull Class<?> dataClass, @NonNull Class<?> resourceClass) {
123	      return this.dataClass.isAssignableFrom(dataClass)
124	          && resourceClass.isAssignableFrom(this.resourceClass);
125	    }
126	  }
127	}
