10	/**
11	 * Contains an ordered list of {@link ResourceEncoder}s capable of encoding arbitrary resource
12	 * types.
13	 */
14	public class ResourceEncoderRegistry {
15	  // TODO: this should probably be a put.
16	  private final List<Entry<?>> encoders = new ArrayList<>();
17	
18	  public synchronized <Z> void append(
19	      @NonNull Class<Z> resourceClass, @NonNull ResourceEncoder<Z> encoder) {
20	    encoders.add(new Entry<>(resourceClass, encoder));
21	  }
22	
23	  public synchronized <Z> void prepend(
24	      @NonNull Class<Z> resourceClass, @NonNull ResourceEncoder<Z> encoder) {
25	    encoders.add(0, new Entry<>(resourceClass, encoder));
26	  }
27	
28	  @SuppressWarnings("unchecked")
29	  @Nullable
30	  public synchronized <Z> ResourceEncoder<Z> get(@NonNull Class<Z> resourceClass) {
31	    //noinspection ForLoopReplaceableByForEach to improve perf
32	    for (int i = 0, size = encoders.size(); i < size; i++) {
33	      Entry<?> entry = encoders.get(i);
34	      if (entry.handles(resourceClass)) {
35	        return (ResourceEncoder<Z>) entry.encoder;
36	      }
37	    }
38	    // TODO: throw an exception here?
39	    return null;
40	  }
41	
42	  private static final class Entry<T> {
43	    private final Class<T> resourceClass;
44	    @Synthetic final ResourceEncoder<T> encoder;
45	
46	    Entry(@NonNull Class<T> resourceClass, @NonNull ResourceEncoder<T> encoder) {
47	      this.resourceClass = resourceClass;
48	      this.encoder = encoder;
49	    }
50	
51	    @Synthetic
