1	package com.bumptech.glide.load.resource.transcode;
2	
3	import androidx.annotation.NonNull;
4	import com.bumptech.glide.util.Synthetic;
5	import java.util.ArrayList;
6	import java.util.List;
7	
8	/**
9	 * A class that allows {@link com.bumptech.glide.load.resource.transcode.ResourceTranscoder}s to be
10	 * registered and retrieved by the classes they convert between.
11	 */
12	public class TranscoderRegistry {
13	  private final List<Entry<?, ?>> transcoders = new ArrayList<>();
14	
15	  /**
16	   * Registers the given {@link com.bumptech.glide.load.resource.transcode.ResourceTranscoder} using
17	   * the given classes so it can later be retrieved using the given classes.
18	   *
19	   * @param decodedClass The class of the resource that the transcoder transcodes from.
20	   * @param transcodedClass The class of the resource that the transcoder transcodes to.
21	   * @param transcoder The transcoder.
22	   * @param <Z> The type of the resource that the transcoder transcodes from.
23	   * @param <R> The type of the resource that the transcoder transcodes to.
24	   */
25	  public synchronized <Z, R> void register(
26	      @NonNull Class<Z> decodedClass,
27	      @NonNull Class<R> transcodedClass,
28	      @NonNull ResourceTranscoder<Z, R> transcoder) {
29	    transcoders.add(new Entry<>(decodedClass, transcodedClass, transcoder));
30	  }
31	
32	  /**
33	   * Returns the currently registered {@link
34	   * com.bumptech.glide.load.resource.transcode.ResourceTranscoder} for the given classes.
35	   *
36	   * @param resourceClass The class of the resource that the transcoder transcodes from.
37	   * @param transcodedClass The class of the resource that the transcoder transcodes to.
38	   * @param <Z> The type of the resource that the transcoder transcodes from.
39	   * @param <R> The type of the resource that the transcoder transcodes to.
40	   */
41	  @NonNull
42	  @SuppressWarnings("unchecked")
43	  public synchronized <Z, R> ResourceTranscoder<Z, R> get(
44	      @NonNull Class<Z> resourceClass, @NonNull Class<R> transcodedClass) {
45	    // For example, there may be a transcoder that can convert a GifDrawable to a Drawable, which
46	    // will be caught above. However, if there is no registered transcoder, we can still just use
47	    // the UnitTranscoder to return the Drawable because the transcode class (Drawable) is
48	    // assignable from the resource class (GifDrawable).
49	    if (transcodedClass.isAssignableFrom(resourceClass)) {
50	      return (ResourceTranscoder<Z, R>) UnitTranscoder.get();
51	    }
52	    for (Entry<?, ?> entry : transcoders) {
53	      if (entry.handles(resourceClass, transcodedClass)) {
54	        return (ResourceTranscoder<Z, R>) entry.transcoder;
55	      }
56	    }
57	
58	    throw new IllegalArgumentException(
59	        "No transcoder registered to transcode from " + resourceClass + " to " + transcodedClass);
60	  }
61	
62	  @NonNull
63	  @SuppressWarnings("unchecked")
64	  public synchronized <Z, R> List<Class<R>> getTranscodeClasses(
65	      @NonNull Class<Z> resourceClass, @NonNull Class<R> transcodeClass) {
66	    List<Class<R>> transcodeClasses = new ArrayList<>();
67	    // GifDrawable -> Drawable is just the UnitTranscoder, as is GifDrawable -> GifDrawable.
68	    if (transcodeClass.isAssignableFrom(resourceClass)) {
69	      transcodeClasses.add(transcodeClass);
70	      return transcodeClasses;
71	    }
72	
73	    for (Entry<?, ?> entry : transcoders) {
