27	 * @param <T> The type of the model being displayed in the list.
28	 */
29	public class ListPreloader<T> implements AbsListView.OnScrollListener {
30	  private final int maxPreload;
31	  private final PreloadTargetQueue preloadTargetQueue;
32	  private final RequestManager requestManager;
33	  private final PreloadModelProvider<T> preloadModelProvider;
34	  private final PreloadSizeProvider<T> preloadDimensionProvider;
35	
36	  private int lastEnd;
37	  private int lastStart;
38	  private int lastFirstVisible = -1;
39	  private int totalItemCount;
40	
41	  private boolean isIncreasing = true;
42	
43	  /**
44	   * An implementation of PreloadModelProvider should provide all the models that should be
45	   * preloaded.
46	   *
47	   * @param <U> The type of the model being preloaded.
48	   */
49	  public interface PreloadModelProvider<U> {
50	
51	    /**
52	     * Returns a {@link List} of models that need to be loaded for the list to display adapter items
53	     * in positions between {@code start} and {@code end}.
54	     *
55	     * <p>{@code position} is the position in the view. If the view contains a mix of types (e.g.
56	     * headers and images) then not every view position will actually have any model to return here.
57	     * If that's the case for the given {@code position}, then return an empty list.
