138	  }
139	
140	  @Override
141	  public void onScrollStateChanged(AbsListView absListView, int scrollState) {
142	    // Do nothing.
143	  }
144	
145	  @Override
146	  public void onScroll(
147	      AbsListView absListView, int firstVisible, int visibleCount, int totalCount) {
148	    if (totalItemCount == 0 && totalCount == 0) {
149	      return;
150	    }
151	    totalItemCount = totalCount;
152	    if (firstVisible > lastFirstVisible) {
