173	      end = to;
174	    } else {
175	      start = to;
176	      end = Math.min(lastStart, from);
177	    }
178	    end = Math.min(totalItemCount, end);
179	    start = Math.min(totalItemCount, Math.max(0, start));
180	
181	    if (from < to) {
182	      // Increasing
183	      for (int i = start; i < end; i++) {
184	        preloadAdapterPosition(
