4	import android.content.pm.ApplicationInfo;
5	import android.content.pm.PackageManager;
6	import android.content.pm.PackageManager.NameNotFoundException;
7	import android.util.Log;
8	import androidx.annotation.Nullable;
9	import java.lang.reflect.InvocationTargetException;
10	import java.util.ArrayList;
11	import java.util.List;
12	
13	/**
14	 * Parses {@link com.bumptech.glide.module.GlideModule} references out of the AndroidManifest file.
15	 */
16	// Used only in javadoc.
17	@SuppressWarnings("deprecation")
18	@Deprecated
19	public final class ManifestParser {
20	  private static final String TAG = "ManifestParser";
21	  private static final String GLIDE_MODULE_VALUE = "GlideModule";
22	
23	  private final Context context;
24	
25	  public ManifestParser(Context context) {
26	    this.context = context;
27	  }
28	
29	  // getApplicationInfo returns null in Compose previews, see #4977 and b/263613353.
30	  @SuppressWarnings("ConstantConditions")
31	  @Nullable
32	  private ApplicationInfo getOurApplicationInfo() throws NameNotFoundException {
33	    return context
34	        .getPackageManager()
35	        .getApplicationInfo(context.getPackageName(), PackageManager.GET_META_DATA);
36	  }
37	
38	  @SuppressWarnings("deprecation")
39	  public List<GlideModule> parse() {
40	    if (Log.isLoggable(TAG, Log.DEBUG)) {
41	      Log.d(TAG, "Loading Glide modules");
42	    }
43	    List<GlideModule> modules = new ArrayList<>();
44	    try {
45	      ApplicationInfo appInfo = getOurApplicationInfo();
46	      if (appInfo == null || appInfo.metaData == null) {
47	        if (Log.isLoggable(TAG, Log.DEBUG)) {
48	          Log.d(TAG, "Got null app info metadata");
49	        }
50	        return modules;
51	      }
52	      if (Log.isLoggable(TAG, Log.VERBOSE)) {
53	        Log.v(TAG, "Got app info metadata: " + appInfo.metaData);
54	      }
55	      for (String key : appInfo.metaData.keySet()) {
56	        if (GLIDE_MODULE_VALUE.equals(appInfo.metaData.get(key))) {
57	          modules.add(parseModule(key));
58	          if (Log.isLoggable(TAG, Log.DEBUG)) {
59	            Log.d(TAG, "Loaded Glide module: " + key);
60	          }
61	        }
62	      }
63	      if (Log.isLoggable(TAG, Log.DEBUG)) {
64	        Log.d(TAG, "Finished loading Glide modules");
65	      }
66	    } catch (PackageManager.NameNotFoundException e) {
67	      if (Log.isLoggable(TAG, Log.ERROR)) {
68	        Log.e(TAG, "Failed to parse glide modules", e);
69	      }
70	    }
71	
72	    return modules;
73	  }
74	
75	  @SuppressWarnings("deprecation")
76	  private static GlideModule parseModule(String className) {
77	    Class<?> clazz;
78	    try {
79	      clazz = Class.forName(className);
80	    } catch (ClassNotFoundException e) {
81	      throw new IllegalArgumentException("Unable to find GlideModule implementation", e);
82	    }
83	
84	    Object module = null;
85	    try {
86	      module = clazz.getDeclaredConstructor().newInstance();
87	      // These can't be combined until API minimum is 19.
88	    } catch (InstantiationException e) {
89	      throwInstantiateGlideModuleException(clazz, e);
90	    } catch (IllegalAccessException e) {
91	      throwInstantiateGlideModuleException(clazz, e);
92	    } catch (NoSuchMethodException e) {
93	      throwInstantiateGlideModuleException(clazz, e);
94	    } catch (InvocationTargetException e) {
95	      throwInstantiateGlideModuleException(clazz, e);
96	    }
97	
98	    if (!(module instanceof GlideModule)) {
99	      throw new RuntimeException("Expected instanceof GlideModule, but found: " + module);
100	    }
101	    return (GlideModule) module;
102	  }
103	
104	  private static void throwInstantiateGlideModuleException(Class<?> clazz, Exception e) {
105	    throw new RuntimeException("Unable to instantiate GlideModule implementation for " + clazz, e);
106	  }
107	}
